// 由 scripts/build-dashboard.mjs 从 dashboard.html 生成，请勿手改。
export default "<!DOCTYPE html>\n<html lang=\"zh-CN\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<meta name=\"robots\" content=\"noindex, nofollow\">\n<title>HGhub · Telemetry</title>\n<style>\n  :root{\n    --ink:#0a0a0a; --paper:#fff; --muted:#6b6b6b; --faint:#9a9a9a;\n    --rule:#e4e4e4; --rule-strong:#0a0a0a;\n    --accent:#4d6bfe; --accent-soft:#eef1ff;\n    --danger:#e63946; --warn:#f0a020; --ok:#1f9d55;\n    --gap:24px; --pad:32px;\n    --dur-fast:120ms; --dur-base:400ms; --dur-slow:1200ms;\n    --ease:cubic-bezier(.2,.7,.2,1);\n  }\n  @media (prefers-reduced-motion: reduce){\n    :root{ --dur-fast:0ms; --dur-base:0ms; --dur-slow:0ms; }\n    *{ animation:none !important; transition:none !important; }\n  }\n  *{ box-sizing:border-box; margin:0; padding:0; }\n  html,body{ background:var(--paper); color:var(--ink); }\n  body{\n    font-family:-apple-system,BlinkMacSystemFont,\"Helvetica Neue\",\"Segoe UI\",Arial,\"PingFang SC\",\"Microsoft YaHei\",sans-serif;\n    font-size:14px; line-height:1.45;\n    -webkit-font-smoothing:antialiased;\n    font-variant-numeric:tabular-nums;\n  }\n  .wrap{ max-width:1440px; margin:0 auto; padding:var(--pad); }\n\n  /* ── 顶栏 ─────────────────────────────── */\n  header{\n    display:flex; align-items:flex-end; justify-content:space-between;\n    gap:var(--gap); padding-bottom:16px;\n    border-bottom:2px solid var(--rule-strong); flex-wrap:wrap;\n  }\n  .brand{ display:flex; align-items:baseline; gap:12px; }\n  .brand h1{\n    font-size:28px; font-weight:700; letter-spacing:-.02em; line-height:1;\n  }\n  .brand .sub{\n    font-size:11px; letter-spacing:.14em; text-transform:uppercase; color:var(--muted);\n  }\n  .controls{ display:flex; align-items:center; gap:8px; flex-wrap:wrap; }\n  .seg{ display:flex; border:1px solid var(--rule-strong); }\n  .seg button{\n    font:inherit; font-size:12px; letter-spacing:.06em;\n    background:var(--paper); color:var(--ink);\n    border:0; border-right:1px solid var(--rule-strong);\n    padding:7px 14px; cursor:pointer;\n    transition:background var(--dur-fast) var(--ease), color var(--dur-fast) var(--ease);\n  }\n  .seg button:last-child{ border-right:0; }\n  .seg button:hover{ background:var(--accent-soft); }\n  .seg button[aria-pressed=\"true\"]{ background:var(--ink); color:var(--paper); }\n  .icon-btn{\n    font:inherit; font-size:12px; letter-spacing:.06em;\n    background:var(--paper); color:var(--ink);\n    border:1px solid var(--rule-strong); padding:7px 14px; cursor:pointer;\n    transition:background var(--dur-fast) var(--ease), color var(--dur-fast) var(--ease);\n  }\n  .icon-btn:hover{ background:var(--ink); color:var(--paper); }\n  .icon-btn:disabled{ opacity:.4; cursor:default; }\n  .stamp{ font-size:11px; color:var(--faint); letter-spacing:.04em; }\n\n  /* ── 网格 ─────────────────────────────── */\n  .grid{ display:grid; grid-template-columns:repeat(12,1fr); gap:var(--gap); margin-top:var(--gap); }\n  .col-3{ grid-column:span 3; } .col-4{ grid-column:span 4; }\n  .col-5{ grid-column:span 5; } .col-6{ grid-column:span 6; }\n  .col-7{ grid-column:span 7; } .col-8{ grid-column:span 8; }\n  .col-12{ grid-column:span 12; }\n  @media (max-width:1199px){\n    .col-3{ grid-column:span 4; } .col-5{ grid-column:span 4; }\n    .col-7{ grid-column:span 8; }\n  }\n  @media (max-width:767px){\n    :root{ --pad:18px; --gap:16px; }\n    .col-3,.col-4,.col-5,.col-6,.col-7,.col-8{ grid-column:span 12; }\n    .brand h1{ font-size:22px; }\n  }\n\n  /* ── KPI ──────────────────────────────── */\n  .kpi{ border-top:1px solid var(--rule); padding-top:12px; }\n  .kpi .label{\n    font-size:10px; letter-spacing:.14em; text-transform:uppercase; color:var(--muted);\n  }\n  .kpi .value{\n    font-size:40px; font-weight:700; letter-spacing:-.03em; line-height:1.05; margin-top:6px;\n  }\n  .kpi .value small{ font-size:16px; font-weight:400; color:var(--muted); margin-left:4px; }\n  .kpi .note{ font-size:11px; color:var(--faint); margin-top:4px; }\n  .kpi.accent .value{ color:var(--accent); }\n\n  /* ── 面板 ─────────────────────────────── */\n  section{ border-top:1px solid var(--rule); padding-top:14px; }\n  section > h2{\n    font-size:11px; letter-spacing:.14em; text-transform:uppercase;\n    font-weight:600; color:var(--muted); margin-bottom:14px;\n    display:flex; justify-content:space-between; align-items:baseline; gap:12px;\n  }\n  section > h2 .hint{ font-size:10px; letter-spacing:.04em; text-transform:none; color:var(--faint); font-weight:400; }\n  .chart{ width:100%; display:block; overflow:visible; }\n  .chart text{ font-size:10px; fill:var(--faint); font-variant-numeric:tabular-nums; }\n  .chart .grid-line{ stroke:var(--rule); stroke-width:1; }\n  .chart .axis{ stroke:var(--rule-strong); stroke-width:1; }\n  .chart .series-line{ fill:none; stroke-width:2; stroke-linecap:round; stroke-linejoin:round; }\n  .chart .series-area{ stroke:none; opacity:.10; }\n  .chart .dot{ r:3; opacity:0; transition:opacity var(--dur-fast) var(--ease); }\n  .chart .hit{ fill:transparent; cursor:crosshair; }\n  .chart .crosshair{ stroke:var(--ink); stroke-width:1; stroke-dasharray:2 3; opacity:0; }\n  .chart .hover-dot{ r:4; opacity:0; }\n  .chart .bar{ transition:opacity var(--dur-fast) var(--ease); }\n  .chart .bar:hover{ opacity:.75; }\n\n  /* 横向条形 */\n  .bars{ display:flex; flex-direction:column; gap:10px; }\n  .bar-row{ display:grid; grid-template-columns:minmax(70px,32%) 1fr auto; gap:10px; align-items:center; }\n  .bar-row .name{ font-size:12px; color:var(--ink); overflow:hidden; text-overflow:ellipsis; white-space:nowrap; }\n  .bar-row .track{ height:10px; background:var(--rule); position:relative; overflow:hidden; }\n  .bar-row .fill{\n    position:absolute; inset:0 auto 0 0; background:var(--accent);\n    transform-origin:left center; animation:grow var(--dur-base) var(--ease) both;\n  }\n  .bar-row .num{ font-size:12px; color:var(--muted); min-width:52px; text-align:right; }\n  @keyframes grow{ from{ transform:scaleX(0); } to{ transform:scaleX(1); } }\n\n  /* 指标网格 */\n  .metrics{ display:grid; grid-template-columns:repeat(auto-fit,minmax(140px,1fr)); gap:16px 24px; }\n  .metric .k{ font-size:10px; letter-spacing:.12em; text-transform:uppercase; color:var(--muted); }\n  .metric .v{ font-size:22px; font-weight:700; letter-spacing:-.02em; margin-top:3px; }\n  .metric .v small{ font-size:11px; font-weight:400; color:var(--muted); margin-left:3px; }\n  .metric .s{ font-size:10px; color:var(--faint); margin-top:2px; }\n\n  /* 崩溃聚合 */\n  .crash-list{ display:flex; flex-direction:column; }\n  .crash-item{ border-top:1px solid var(--rule); padding:12px 0; }\n  .crash-item:first-child{ border-top:0; }\n  .crash-head{ display:flex; align-items:baseline; gap:10px; cursor:pointer; }\n  .crash-count{\n    font-size:18px; font-weight:700; color:var(--danger); min-width:44px;\n    font-variant-numeric:tabular-nums;\n  }\n  .crash-type{ font-size:11px; letter-spacing:.08em; text-transform:uppercase; color:var(--muted); }\n  .crash-reason{ font-size:13px; color:var(--ink); flex:1; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; }\n  .crash-meta{ font-size:11px; color:var(--faint); margin-left:auto; white-space:nowrap; }\n  .crash-stack{\n    margin-top:8px; padding:10px 12px; background:#fafafa; border-left:2px solid var(--danger);\n    font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;\n    font-size:11px; line-height:1.6; color:var(--muted); white-space:pre-wrap;\n    word-break:break-all; max-height:0; overflow:hidden;\n    transition:max-height var(--dur-base) var(--ease), opacity var(--dur-fast) var(--ease);\n    opacity:0;\n  }\n  .crash-item.open .crash-stack{ max-height:400px; opacity:1; overflow:auto; }\n  .crash-versions{ margin-top:6px; display:flex; gap:8px; flex-wrap:wrap; }\n  .crash-versions span{\n    font-size:10px; letter-spacing:.04em; color:var(--muted);\n    border:1px solid var(--rule); padding:1px 6px;\n  }\n\n  /* 明细表 */\n  .table-wrap{ overflow-x:auto; }\n  table{ width:100%; border-collapse:collapse; font-size:12px; }\n  th,td{ padding:8px 10px; text-align:right; border-bottom:1px solid var(--rule); white-space:nowrap; }\n  th:first-child, td:first-child{ text-align:left; }\n  thead th{\n    font-size:10px; letter-spacing:.1em; text-transform:uppercase;\n    color:var(--muted); font-weight:600; cursor:pointer; user-select:none;\n    border-bottom:1px solid var(--rule-strong);\n  }\n  thead th:hover{ color:var(--ink); }\n  tbody tr:hover{ background:var(--accent-soft); }\n\n  /* 图例 */\n  .legend{ display:flex; gap:16px; flex-wrap:wrap; margin-bottom:10px; }\n  .legend button{\n    font:inherit; font-size:11px; background:none; border:0; padding:0;\n    display:flex; align-items:center; gap:6px; cursor:pointer; color:var(--ink);\n    transition:opacity var(--dur-fast) var(--ease);\n  }\n  .legend button[aria-pressed=\"false\"]{ opacity:.35; }\n  .legend .swatch{ width:10px; height:10px; display:inline-block; }\n\n  /* 状态 */\n  .state{ padding:64px 0; text-align:center; color:var(--muted); font-size:13px; }\n  .state.error{ color:var(--danger); }\n  .skeleton{ height:12px; background:var(--rule); animation:pulse 900ms ease-in-out infinite alternate; }\n  @keyframes pulse{ from{ opacity:.45; } to{ opacity:1; } }\n\n  /* 登录页 */\n  .gate{ max-width:420px; margin:18vh auto 0; }\n  .gate h1{ font-size:24px; font-weight:700; letter-spacing:-.02em; }\n  .gate p{ font-size:12px; color:var(--muted); margin-top:8px; }\n  .gate form{ display:flex; gap:8px; margin-top:24px; }\n  .gate input{\n    flex:1; font:inherit; font-size:13px; padding:9px 12px;\n    border:1px solid var(--rule-strong); background:var(--paper); color:var(--ink);\n    outline:none;\n  }\n  .gate input:focus{ border-color:var(--accent); }\n  .gate button{\n    font:inherit; font-size:13px; padding:9px 18px; cursor:pointer;\n    background:var(--ink); color:var(--paper); border:1px solid var(--ink);\n  }\n  .gate .err{ color:var(--danger); font-size:12px; margin-top:10px; }\n\n  /* tooltip */\n  .tip{\n    position:fixed; pointer-events:none; z-index:50;\n    background:var(--ink); color:var(--paper);\n    font-size:11px; line-height:1.5; padding:6px 9px; white-space:nowrap;\n    opacity:0; transform:translate(-50%,-130%);\n    transition:opacity var(--dur-fast) var(--ease);\n  }\n  .tip.on{ opacity:1; }\n</style>\n</head>\n<body>\n<div class=\"wrap\">\n  <header>\n    <div class=\"brand\">\n      <h1>HGhub</h1>\n      <span class=\"sub\">Telemetry · 匿名聚合</span>\n    </div>\n    <div class=\"controls\">\n      <div class=\"seg\" id=\"range\" role=\"group\" aria-label=\"时间范围\">\n        <button data-days=\"7\" aria-pressed=\"false\">7D</button>\n        <button data-days=\"30\" aria-pressed=\"true\">30D</button>\n        <button data-days=\"90\" aria-pressed=\"false\">90D</button>\n      </div>\n      <button class=\"icon-btn\" id=\"refresh\" title=\"刷新\">刷新</button>\n      <span class=\"stamp\" id=\"stamp\"></span>\n    </div>\n  </header>\n\n  <main id=\"main\">\n    <div class=\"state\" id=\"state\">加载中…</div>\n  </main>\n</div>\n<div class=\"tip\" id=\"tip\"></div>\n\n<script>\n(function(){\n  'use strict';\n\n  var ACCENT = '#4d6bfe';\n  var DANGER = '#e63946';\n  var WARN = '#f0a020';\n  var OK = '#1f9d55';\n\n  var state = {\n    days: 30,\n    data: null,\n    hidden: {},\n    sortKey: 'day',\n    sortDir: 'desc'\n  };\n\n  var elMain = document.getElementById('main');\n  var elState = document.getElementById('state');\n  var elStamp = document.getElementById('stamp');\n  var elTip = document.getElementById('tip');\n\n  /* ── 工具 ─────────────────────────────── */\n\n  function fmt(n){\n    if (n === null || n === undefined || isNaN(n)) return '—';\n    if (Math.abs(n) >= 1000000) return (n/1000000).toFixed(1) + 'M';\n    if (Math.abs(n) >= 10000) return (n/1000).toFixed(1) + 'k';\n    return String(Math.round(n));\n  }\n  function fmtExact(n){\n    if (n === null || n === undefined || isNaN(n)) return '—';\n    return String(Math.round(n)).replace(/\\B(?=(\\d{3})+(?!\\d))/g, ',');\n  }\n  function fmtDur(sec){\n    if (!sec || sec <= 0) return '0s';\n    if (sec < 60) return Math.round(sec) + 's';\n    if (sec < 3600) return Math.round(sec/60) + 'm';\n    return (sec/3600).toFixed(1) + 'h';\n  }\n  function esc(s){\n    return String(s === null || s === undefined ? '' : s)\n      .replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;')\n      .replace(/\"/g,'&quot;').replace(/'/g,'&#39;');\n  }\n  function dayLabel(d){\n    var s = String(d);\n    return s.length === 8 ? (s.slice(4,6) + '/' + s.slice(6,8)) : s;\n  }\n  function dayFull(d){\n    var s = String(d);\n    return s.length === 8 ? (s.slice(0,4) + '-' + s.slice(4,6) + '-' + s.slice(6,8)) : s;\n  }\n  function reduced(){\n    return window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;\n  }\n\n  /* ── 数字滚动 ─────────────────────────── */\n\n  function countUp(el, to, suffix){\n    var from = 0;\n    var dur = reduced() ? 0 : 800;\n    var start = performance.now();\n    function tick(now){\n      var p = dur <= 0 ? 1 : Math.min(1, (now - start) / dur);\n      var e = 1 - Math.pow(1 - p, 3);\n      var v = from + (to - from) * e;\n      el.textContent = fmt(v) + (suffix || '');\n      if (p < 1) requestAnimationFrame(tick);\n      else el.textContent = fmt(to) + (suffix || '');\n    }\n    requestAnimationFrame(tick);\n  }\n\n  /* ── tooltip ──────────────────────────── */\n\n  function showTip(html, x, y){\n    elTip.innerHTML = html;\n    elTip.style.left = x + 'px';\n    elTip.style.top = y + 'px';\n    elTip.classList.add('on');\n  }\n  function hideTip(){ elTip.classList.remove('on'); }\n\n  /* ── 折线图 ───────────────────────────── */\n\n  function lineChart(series, opts){\n    opts = opts || {};\n    var W = 1000, H = opts.height || 240;\n    var padL = 44, padR = 12, padT = 12, padB = 26;\n    var iw = W - padL - padR, ih = H - padT - padB;\n\n    var all = [];\n    series.forEach(function(s){ s.values.forEach(function(v){ if (v !== null && v !== undefined) all.push(v); }); });\n    var max = all.length ? Math.max.apply(null, all) : 0;\n    var min = opts.zeroBase !== false ? 0 : (all.length ? Math.min.apply(null, all) : 0);\n    if (max === min) max = min + 1;\n    var n = series[0] ? series[0].values.length : 0;\n\n    function x(i){ return padL + (n <= 1 ? iw/2 : (i / (n - 1)) * iw); }\n    function y(v){ return padT + ih - ((v - min) / (max - min)) * ih; }\n\n    var svg = ['<svg class=\"chart\" viewBox=\"0 0 ' + W + ' ' + H + '\" preserveAspectRatio=\"none\" role=\"img\">'];\n\n    // 横向网格 + y 轴刻度\n    var ticks = 4;\n    for (var t = 0; t <= ticks; t++){\n      var val = min + (max - min) * (t / ticks);\n      var yy = y(val);\n      svg.push('<line class=\"grid-line\" x1=\"' + padL + '\" y1=\"' + yy + '\" x2=\"' + (W - padR) + '\" y2=\"' + yy + '\"/>');\n      svg.push('<text x=\"' + (padL - 8) + '\" y=\"' + (yy + 3) + '\" text-anchor=\"end\">' + fmt(val) + '</text>');\n    }\n    svg.push('<line class=\"axis\" x1=\"' + padL + '\" y1=\"' + (padT + ih) + '\" x2=\"' + (W - padR) + '\" y2=\"' + (padT + ih) + '\"/>');\n\n    // x 轴标签（最多 8 个）\n    var step = Math.max(1, Math.ceil(n / 8));\n    for (var i = 0; i < n; i += step){\n      svg.push('<text x=\"' + x(i) + '\" y=\"' + (H - 8) + '\" text-anchor=\"middle\">' + esc(dayLabel(opts.labels[i])) + '</text>');\n    }\n\n    // 系列\n    series.forEach(function(s){\n      if (state.hidden[s.key]) return;\n      var pts = [];\n      for (var i = 0; i < s.values.length; i++){\n        var v = s.values[i];\n        if (v === null || v === undefined) continue;\n        pts.push([x(i), y(v)]);\n      }\n      if (!pts.length) return;\n      var d = pts.map(function(p, idx){ return (idx ? 'L' : 'M') + p[0].toFixed(1) + ' ' + p[1].toFixed(1); }).join(' ');\n      if (s.area){\n        var base = padT + ih;\n        var da = d + ' L' + pts[pts.length-1][0].toFixed(1) + ' ' + base + ' L' + pts[0][0].toFixed(1) + ' ' + base + ' Z';\n        svg.push('<path class=\"series-area\" d=\"' + da + '\" fill=\"' + s.color + '\"/>');\n      }\n      svg.push('<path class=\"series-line\" d=\"' + d + '\" stroke=\"' + s.color + '\"' +\n        (reduced() ? '' : ' stroke-dasharray=\"4000\" stroke-dashoffset=\"4000\" style=\"animation:draw ' + (opts.drawMs || 1200) + 'ms var(--ease) forwards\"') + '/>');\n      pts.forEach(function(p, idx){\n        svg.push('<circle class=\"dot\" cx=\"' + p[0] + '\" cy=\"' + p[1] + '\" fill=\"' + s.color + '\"/>');\n      });\n    });\n\n    // 交互层\n    svg.push('<line class=\"crosshair\" x1=\"0\" y1=\"' + padT + '\" x2=\"0\" y2=\"' + (padT + ih) + '\"/>');\n    svg.push('<rect class=\"hit\" x=\"' + padL + '\" y=\"' + padT + '\" width=\"' + iw + '\" height=\"' + ih + '\"/>');\n    svg.push('</svg>');\n\n    var wrap = document.createElement('div');\n    wrap.innerHTML = svg.join('');\n    var svgEl = wrap.firstChild;\n    var hit = svgEl.querySelector('.hit');\n    var cross = svgEl.querySelector('.crosshair');\n\n    hit.addEventListener('mousemove', function(ev){\n      var box = svgEl.getBoundingClientRect();\n      var px = (ev.clientX - box.left) / box.width * W;\n      var idx = n <= 1 ? 0 : Math.round((px - padL) / iw * (n - 1));\n      idx = Math.max(0, Math.min(n - 1, idx));\n      var cx = x(idx);\n      cross.setAttribute('x1', cx); cross.setAttribute('x2', cx);\n      cross.style.opacity = '1';\n      var rows = series.filter(function(s){ return !state.hidden[s.key]; }).map(function(s){\n        var v = s.values[idx];\n        return '<div><span style=\"display:inline-block;width:8px;height:8px;background:' + s.color + ';margin-right:6px\"></span>' +\n               esc(s.name) + ' ' + fmtExact(v) + '</div>';\n      }).join('');\n      showTip('<div style=\"opacity:.7;margin-bottom:3px\">' + dayFull(opts.labels[idx]) + '</div>' + rows,\n        ev.clientX, ev.clientY);\n    });\n    hit.addEventListener('mouseleave', function(){\n      cross.style.opacity = '0';\n      hideTip();\n    });\n\n    return svgEl;\n  }\n\n  /* ── 横向条形 ─────────────────────────── */\n\n  function barList(items, opts){\n    opts = opts || {};\n    var max = items.reduce(function(m, it){ return Math.max(m, it.value); }, 0) || 1;\n    var box = document.createElement('div');\n    box.className = 'bars';\n    items.slice(0, opts.limit || 10).forEach(function(it, i){\n      var row = document.createElement('div');\n      row.className = 'bar-row';\n      var pct = Math.max(1, (it.value / max) * 100);\n      row.innerHTML =\n        '<span class=\"name\" title=\"' + esc(it.name) + '\">' + esc(it.name) + '</span>' +\n        '<span class=\"track\"><span class=\"fill\" style=\"width:' + pct + '%;background:' + (it.color || ACCENT) +\n          ';animation-delay:' + (reduced() ? 0 : i * 40) + 'ms\"></span></span>' +\n        '<span class=\"num\">' + fmtExact(it.value) + '</span>';\n      box.appendChild(row);\n    });\n    if (!items.length){\n      box.innerHTML = '<div class=\"state\" style=\"padding:24px 0\">暂无数据</div>';\n    }\n    return box;\n  }\n\n  /* ── 渲染 ─────────────────────────────── */\n\n  function kpiCard(label, value, note, accent){\n    var d = document.createElement('div');\n    d.className = 'kpi col-3' + (accent ? ' accent' : '');\n    d.innerHTML = '<div class=\"label\">' + esc(label) + '</div>' +\n                  '<div class=\"value\"><span class=\"num\">0</span></div>' +\n                  '<div class=\"note\">' + esc(note || '') + '</div>';\n    d._value = value;\n    return d;\n  }\n\n  function section(title, hint, child, cls){\n    var s = document.createElement('section');\n    s.className = cls || 'col-12';\n    s.innerHTML = '<h2>' + esc(title) + (hint ? '<span class=\"hint\">' + esc(hint) + '</span>' : '') + '</h2>';\n    if (child) s.appendChild(child);\n    return s;\n  }\n\n  function legend(series){\n    var box = document.createElement('div');\n    box.className = 'legend';\n    series.forEach(function(s){\n      var b = document.createElement('button');\n      b.setAttribute('aria-pressed', state.hidden[s.key] ? 'false' : 'true');\n      b.innerHTML = '<span class=\"swatch\" style=\"background:' + s.color + '\"></span>' + esc(s.name);\n      b.addEventListener('click', function(){\n        state.hidden[s.key] = !state.hidden[s.key];\n        render();\n      });\n      box.appendChild(b);\n    });\n    return box;\n  }\n\n  function render(){\n    var d = state.data;\n    if (!d){ return; }\n    elMain.innerHTML = '';\n\n    var grid = document.createElement('div');\n    grid.className = 'grid';\n\n    /* KPI */\n    var kpis = [\n      kpiCard('安装数', d.devices_total, '累积去重设备', true),\n      kpiCard('DAU', (d.daily.length ? d.daily[d.daily.length-1].devices : 0), '最近一天活跃'),\n      kpiCard('7 日回访', d.returning_7d_ratio, d.returning_7d + ' 台回访'),\n      kpiCard('平均时长', d.avg_duration_sec_per_session, '每次会话（秒）')\n    ];\n    kpis.forEach(function(k){ grid.appendChild(k); });\n\n    /* 折线：DAU + 新增 */\n    var labels = d.daily.map(function(r){ return r.day; });\n    var newMap = {};\n    (d.new_devices_daily || []).forEach(function(r){ newMap[r.day] = r.devices; });\n    var dauSeries = [\n      { key:'dau', name:'DAU', color:ACCENT, area:true,\n        values: d.daily.map(function(r){ return r.devices; }) },\n      { key:'new', name:'新增设备', color:'#0a0a0a',\n        values: labels.map(function(l){ return newMap[l] || 0; }) }\n    ];\n    var lineWrap = document.createElement('div');\n    lineWrap.appendChild(legend(dauSeries));\n    lineWrap.appendChild(lineChart(dauSeries, { labels: labels, height: 240 }));\n    grid.appendChild(section('活跃与新增', '按天 · 悬停查看明细', lineWrap, 'col-12'));\n\n    /* VV 与时长 */\n    var vvSeries = [\n      { key:'vv', name:'播放次数 VV', color:ACCENT, area:true,\n        values: d.daily.map(function(r){ return r.vv; }) },\n      { key:'dur', name:'时长（分钟）', color:WARN,\n        values: d.daily.map(function(r){ return Math.round((r.duration_sec || 0) / 60); }) }\n    ];\n    var vvWrap = document.createElement('div');\n    vvWrap.appendChild(legend(vvSeries));\n    vvWrap.appendChild(lineChart(vvSeries, { labels: labels, height: 220 }));\n    grid.appendChild(section('播放与时长', 'VV / 分钟', vvWrap, 'col-7'));\n\n    /* 版本分布 */\n    var verItems = (d.by_version || []).map(function(r){ return { name: r.version, value: r.n }; });\n    grid.appendChild(section('版本分布', verItems.length + ' 个版本', barList(verItems), 'col-5'));\n\n    /* 机型分布 */\n    var modelItems = (d.by_model || []).map(function(r){ return { name: r.model, value: r.n }; });\n    grid.appendChild(section('机型分布', modelItems.length + ' 种机型', barList(modelItems, { limit: 8 }), 'col-6'));\n\n    /* 系统版本 */\n    var osItems = (d.by_os || []).map(function(r){ return { name: r.os, value: r.n }; });\n    grid.appendChild(section('系统版本', osItems.length + ' 种', barList(osItems, { limit: 8 }), 'col-6'));\n\n    /* 播放失败分桶 */\n    var fb = d.playback.fail_breakdown || {};\n    var failItems = [\n      { name:'网络', value: fb.network || 0, color: WARN },\n      { name:'鉴权', value: fb.auth || 0, color: DANGER },\n      { name:'资源不存在', value: fb.notfound || 0, color:'#8a8a8a' },\n      { name:'服务端', value: fb.server || 0, color:'#b03a2e' },\n      { name:'其他', value: fb.other || 0, color:'#c9c9c9' }\n    ];\n    grid.appendChild(section('播放失败分桶',\n      '失败率 ' + d.playback.play_fail_rate + '% · 完播率 ' + d.playback.play_complete_rate + '%',\n      barList(failItems), 'col-6'));\n\n    /* 启动耗时 */\n    var startupItems = [\n      { name:'均值', value: d.startup.avg_ms, color: ACCENT },\n      { name:'P50', value: d.startup.avg_p50_ms, color:'#7b8ffd' },\n      { name:'P90', value: d.startup.avg_p90_ms, color:'#0a0a0a' }\n    ];\n    grid.appendChild(section('启动耗时', d.startup.samples + ' 个样本（毫秒）',\n      barList(startupItems), 'col-6'));\n\n    /* 画质与超分 */\n    var qualityItems = [\n      { name:'高清 HD', value: d.quality.hd, color: ACCENT },\n      { name:'标准 SD', value: d.quality.sd, color:'#c9c9c9' },\n      { name:'超分可用', value: d.quality.sr_supported, color: OK },\n      { name:'超分开启', value: d.quality.sr_on, color:'#3bb273' }\n    ];\n    grid.appendChild(section('画质与超分',\n      'HD 占比 ' + d.quality.hd_ratio + '% · 超分支持率 ' + d.quality.sr_support_rate + '%',\n      barList(qualityItems), 'col-6'));\n\n    /* 页面分布 */\n    var pg = d.pages || {};\n    var pageItems = [\n      { name:'首页', value: pg.home || 0 },\n      { name:'搜索', value: pg.search || 0 },\n      { name:'分类', value: pg.category || 0 },\n      { name:'我的', value: pg.profile || 0 },\n      { name:'播放页', value: pg.player || 0 }\n    ];\n    grid.appendChild(section('页面访问', '按进入次数', barList(pageItems), 'col-6'));\n\n    /* 设备指标 */\n    grid.appendChild(section('设备指标', '内存 / 磁盘 / 功耗 · 区间均值', devicePanel(d), 'col-6'));\n\n    /* 线路质量 */\n    grid.appendChild(section('线路质量', '主站 / 镜像请求与延迟', linePanel(d), 'col-6'));\n\n    /* 崩溃聚合 */\n    var cr = d.crash || { total: 0, groups: [] };\n    grid.appendChild(section('崩溃聚合',\n      '共 ' + cr.total + ' 次 · ' + cr.groups.length + ' 个分组 · 点击展开堆栈',\n      crashPanel(d), 'col-12'));\n\n    /* 明细表 */\n    grid.appendChild(section('按天明细', '点击表头排序', buildTable(d), 'col-12'));\n\n    elMain.appendChild(grid);\n\n    /* KPI 数字滚动 */\n    kpis.forEach(function(k){\n      var numEl = k.querySelector('.num');\n      countUp(numEl, k._value || 0, '');\n    });\n\n    elStamp.textContent = '更新于 ' + new Date(d.generated_at).toLocaleString('zh-CN', { hour12:false });\n  }\n\n  function fmtBytes(b){\n    if (!b || b <= 0) return '—';\n    if (b >= 1073741824) return (b / 1073741824).toFixed(2) + ' GB';\n    if (b >= 1048576) return (b / 1048576).toFixed(1) + ' MB';\n    if (b >= 1024) return (b / 1024).toFixed(0) + ' KB';\n    return b + ' B';\n  }\n\n  function metricItem(k, v, unit, sub){\n    return '<div class=\"metric\"><div class=\"k\">' + esc(k) + '</div>' +\n      '<div class=\"v\">' + esc(v) + (unit ? '<small>' + esc(unit) + '</small>' : '') + '</div>' +\n      (sub ? '<div class=\"s\">' + esc(sub) + '</div>' : '') + '</div>';\n  }\n\n  function devicePanel(d){\n    var dv = d.device || {};\n    var box = document.createElement('div');\n    box.className = 'metrics';\n    box.innerHTML =\n      metricItem('内存 PSS 均值', fmt(dv.mem_pss_avg_kb), 'KB') +\n      metricItem('内存 PSS 峰值', fmt(dv.mem_peak_kb), 'KB') +\n      metricItem('虚拟内存 VSS', fmt(dv.mem_vss_avg_kb), 'KB') +\n      metricItem('磁盘 · 安装', fmtBytes(dv.disk_app_avg_bytes)) +\n      metricItem('磁盘 · 缓存', fmtBytes(dv.disk_cache_avg_bytes)) +\n      metricItem('磁盘 · 数据', fmtBytes(dv.disk_data_avg_bytes)) +\n      metricItem('平均耗电', dv.soc_drain_avg_pct, '%',\n        dv.soc_drain_samples ? dv.soc_drain_samples + ' 个未充电会话' : '无有效样本') +\n      metricItem('电池温度', dv.temp_max_c, '°C', '均值 ' + (dv.temp_avg_c || 0) + '°C');\n    return box;\n  }\n\n  function linePanel(d){\n    var ln = d.lines || {};\n    var box = document.createElement('div');\n    var totalReq = (ln.primary_ok || 0) + (ln.primary_fail || 0) +\n                   (ln.mirror_ok || 0) + (ln.mirror_fail || 0);\n    var bars = document.createElement('div');\n    bars.className = 'metrics';\n    bars.innerHTML =\n      metricItem('主站请求', fmt(ln.primary_ok), '',\n        '失败 ' + (ln.primary_fail || 0) + ' · ' + (ln.primary_fail_rate || 0) + '%') +\n      metricItem('镜像请求', fmt(ln.mirror_ok), '',\n        '失败 ' + (ln.mirror_fail || 0) + ' · ' + (ln.mirror_fail_rate || 0) + '%') +\n      metricItem('镜像占比', ln.mirror_share || 0, '%', '共 ' + fmt(totalReq) + ' 次请求') +\n      metricItem('换线次数', fmt(ln.switches), '', '自动 + 手动') +\n      metricItem('延迟均值', fmt(ln.latency_avg_ms), 'ms') +\n      metricItem('延迟 P90', fmt(ln.latency_p90_ms), 'ms');\n    box.appendChild(bars);\n    if (totalReq > 0) {\n      var bar = document.createElement('div');\n      bar.style.cssText = 'margin-top:16px;display:flex;height:10px;background:var(--rule)';\n      var pPct = ((ln.primary_ok || 0) + (ln.primary_fail || 0)) / totalReq * 100;\n      bar.innerHTML =\n        '<div style=\"width:' + pPct + '%;background:' + ACCENT + '\"></div>' +\n        '<div style=\"width:' + (100 - pPct) + '%;background:' + WARN + '\"></div>';\n      box.appendChild(bar);\n      var legend = document.createElement('div');\n      legend.style.cssText = 'margin-top:8px;display:flex;gap:16px;font-size:11px;color:var(--muted)';\n      legend.innerHTML =\n        '<span><span style=\"display:inline-block;width:8px;height:8px;background:' + ACCENT + ';margin-right:6px\"></span>主站</span>' +\n        '<span><span style=\"display:inline-block;width:8px;height:8px;background:' + WARN + ';margin-right:6px\"></span>镜像</span>';\n      box.appendChild(legend);\n    }\n    return box;\n  }\n\n  function crashPanel(d){\n    var c = d.crash || { total: 0, groups: [] };\n    var box = document.createElement('div');\n    box.className = 'crash-list';\n    if (!c.groups.length){\n      box.innerHTML = '<div class=\"state\" style=\"padding:24px 0\">暂无崩溃记录</div>';\n      return box;\n    }\n    c.groups.forEach(function(g){\n      var item = document.createElement('div');\n      item.className = 'crash-item';\n      var versions = (g.versions || []).map(function(v){\n        return '<span>v' + esc(v.version) + ' ×' + v.count + '</span>';\n      }).join('');\n      var last = g.last_seen ? new Date(g.last_seen * 1000).toLocaleString('zh-CN', { hour12:false }) : '—';\n      item.innerHTML =\n        '<div class=\"crash-head\">' +\n          '<span class=\"crash-count\">' + g.count + '×</span>' +\n          '<span class=\"crash-type\">' + esc(g.type) + '</span>' +\n          '<span class=\"crash-reason\">' + esc(g.reason || g.message || '(无原因)') + '</span>' +\n          '<span class=\"crash-meta\">最近 ' + esc(last) + '</span>' +\n        '</div>' +\n        '<div class=\"crash-versions\">' + versions + '</div>' +\n        '<div class=\"crash-stack\">' + esc(g.stack || g.message || '(无堆栈)') + '</div>';\n      item.querySelector('.crash-head').addEventListener('click', function(){\n        item.classList.toggle('open');\n      });\n      box.appendChild(item);\n    });\n    return box;\n  }\n\n  function buildTable(d){\n    var cols = [\n      { key:'day', label:'日期', fmt: dayFull },\n      { key:'devices', label:'DAU', fmt: fmtExact },\n      { key:'sessions', label:'启动', fmt: fmtExact },\n      { key:'duration_sec', label:'时长', fmt: fmtDur },\n      { key:'vv', label:'VV', fmt: fmtExact },\n      { key:'play_complete', label:'完播', fmt: fmtExact },\n      { key:'play_fail', label:'失败', fmt: fmtExact },\n      { key:'avg_startup_ms', label:'启动ms', fmt: fmtExact },\n      { key:'crash', label:'崩溃', fmt: fmtExact }\n    ];\n    var rows = d.daily.slice();\n    var sk = state.sortKey, sd = state.sortDir === 'asc' ? 1 : -1;\n    rows.sort(function(a, b){\n      var x = a[sk], y = b[sk];\n      if (x === y) return 0;\n      return (x > y ? 1 : -1) * sd;\n    });\n\n    var wrap = document.createElement('div');\n    wrap.className = 'table-wrap';\n    var html = ['<table><thead><tr>'];\n    cols.forEach(function(c){\n      html.push('<th data-key=\"' + c.key + '\">' + esc(c.label) +\n        (state.sortKey === c.key ? (state.sortDir === 'asc' ? ' ↑' : ' ↓') : '') + '</th>');\n    });\n    html.push('</tr></thead><tbody>');\n    if (!rows.length){\n      html.push('<tr><td colspan=\"' + cols.length + '\" style=\"text-align:center;color:var(--faint);padding:24px\">暂无数据</td></tr>');\n    }\n    rows.forEach(function(r){\n      html.push('<tr>');\n      cols.forEach(function(c){\n        html.push('<td>' + esc(c.fmt ? c.fmt(r[c.key]) : (r[c.key] === undefined ? '—' : r[c.key])) + '</td>');\n      });\n      html.push('</tr>');\n    });\n    html.push('</tbody></table>');\n    wrap.innerHTML = html.join('');\n\n    wrap.querySelectorAll('th').forEach(function(th){\n      th.addEventListener('click', function(){\n        var k = th.getAttribute('data-key');\n        if (state.sortKey === k){\n          state.sortDir = state.sortDir === 'asc' ? 'desc' : 'asc';\n        } else {\n          state.sortKey = k;\n          state.sortDir = 'desc';\n        }\n        render();\n      });\n    });\n    return wrap;\n  }\n\n  /* ── 数据加载 ─────────────────────────── */\n\n  function setState(text, isError){\n    elMain.innerHTML = '<div class=\"state' + (isError ? ' error' : '') + '\">' + esc(text) + '</div>';\n  }\n\n  function load(days){\n    state.days = days;\n    document.querySelectorAll('#range button').forEach(function(b){\n      b.setAttribute('aria-pressed', String(Number(b.getAttribute('data-days')) === days));\n    });\n    var btn = document.getElementById('refresh');\n    btn.disabled = true;\n    if (!state.data) setState('加载中…');\n\n    fetch('/api/stats?days=' + days, { credentials: 'same-origin' })\n      .then(function(r){\n        if (r.status === 401 || r.status === 403) throw new Error('unauthorized');\n        if (!r.ok) throw new Error('HTTP ' + r.status);\n        return r.json();\n      })\n      .then(function(json){\n        state.data = json;\n        render();\n      })\n      .catch(function(err){\n        if (err.message === 'unauthorized'){\n          location.href = '/dashboard';\n          return;\n        }\n        setState('加载失败：' + err.message, true);\n      })\n      .finally(function(){\n        btn.disabled = false;\n      });\n  }\n\n  document.querySelectorAll('#range button').forEach(function(b){\n    b.addEventListener('click', function(){\n      var days = Number(b.getAttribute('data-days'));\n      if (days === state.days) return;\n      load(days);\n    });\n  });\n  document.getElementById('refresh').addEventListener('click', function(){\n    load(state.days);\n  });\n\n  // 折线描边动画\n  var style = document.createElement('style');\n  style.textContent = '@keyframes draw{ to{ stroke-dashoffset:0; } }';\n  document.head.appendChild(style);\n\n  load(30);\n})();\n</script>\n</body>\n</html>\n";
